lessons.solution_code:
def format_conversation_log(user_id: int, prompt: str, response: str) -> dict:
    return {
        "user_id": user_id,
        "prompt": prompt,
        "response": response,
        "tokens": len(prompt.split()) + len(response.split())
    }
